-- =====================================================================
-- Security & catalogue verification gate (Revision 6)
-- security_verify() returns one row per violation. The migration FAILS if any row is returned,
-- and the test suite calls it again after every scenario.
-- =====================================================================
CREATE OR REPLACE FUNCTION public.security_expected_client_functions()
RETURNS text[] AS $$
  -- The complete list of functions the authenticated role may EXECUTE (reviewed allow-list).
  -- Anything not listed (webhooks, workers, schedulers, ledger/scoring internals) is denied.
  SELECT ARRAY[
    'accept_invitation(text)',
    'add_intervention(uuid,uuid,intervention_type,text,text,uuid,date)',
    'anonymise_student(uuid)',
    'apply_wallet_to_invoice(uuid,bigint)',
    'approve_parent_report(uuid,jsonb)',
    'approve_refund(uuid,text)',
    'assign_intervention(uuid,date,uuid)',
    'attach_checkout(uuid,text,text)',
    'available_exams()',
    'can_manage_membership(uuid)',
    'can_manage_organisation(uuid)',
    'can_manage_role(uuid,uuid,boolean)',
    'can_manage_role_permissions(uuid)',
    'can_manage_settings(uuid)',
    'can_pay_for_student(uuid)',
    'can_read_audit(uuid)',
    'can_read_membership(uuid,uuid)',
    'can_read_role(uuid)',
    'can_read_role_permissions(uuid)',
    'can_read_settings(uuid)',
    'can_read_user(uuid)',
    'can_view_student(uuid)',
    'cancel_ai_job(uuid)',
    'close_exam(uuid)',
    'complete_refund(uuid,text)',
    'create_invoice(uuid,jsonb,uuid,date,text)',
    'create_organisation(text,text,org_type,text)',
    'current_org_id()',
    'current_student_id()',
    'current_user_id()',
    'dismiss_diagnosis(uuid,text)',
    'draft_parent_report(uuid,date,date,text)',
    'draft_parent_reports_for_class(uuid,date,date)',
    'generate_exam_from_blueprint(uuid)',
    'get_attempt_paper(uuid)',
    'grant_organisation_owner(uuid)',
    'has_permission(text)',
    'initiate_payment(uuid,payment_provider,bigint,text,text)',
    'invite_member(text,text)',
    'is_active_org_member(uuid)',
    'is_eligible(uuid,uuid)',
    'is_org_member()',
    'is_platform_admin()',
    'is_self_or_parent(uuid)',
    'issue_invoice(uuid)',
    'learning_dashboard(uuid)',
    'mark_intervention_done(uuid)',
    'mark_report_sent(uuid,text)',
    'mark_response(uuid,numeric,text)',
    'mastery_level(numeric,numeric)',
    'my_attempt_review(uuid)',
    'my_recommendations(boolean)',
    'price_for(uuid,uuid)',
    'publish_exam(uuid)',
    'publish_note_version(uuid,content_visibility)',
    'publish_question_version(uuid,content_visibility)',
    'rebuild_mastery(uuid)',
    'record_manual_payment(uuid,bigint,payment_provider,uuid,text,timestamp with time zone,text,text)',
    'record_recommendation_event(uuid,text)',
    'reject_refund(uuid,text)',
    'release_results(uuid,boolean)',
    'request_ai_diagnosis_explanation(uuid)',
    'request_ai_note(uuid,text,text,text)',
    'request_ai_questions(uuid,integer,question_type,difficulty_level,cognitive_level,text,text)',
    'request_ai_report_comment(uuid)',
    'request_ai_student_review(uuid,text)',
    'request_refund(uuid,bigint,text,refund_source)',
    'results_for_student(uuid)',
    'review_ai_diagnostic(uuid,boolean)',
    'revoke_organisation_owner(uuid,text)',
    'save_response(uuid,uuid,jsonb,integer,boolean)',
    'search_notes(text,uuid)',
    'set_intervention_status(uuid,intervention_status)',
    'staff_can_view_results(uuid)',
    'start_attempt(uuid,inet,text)',
    'submit_attempt(uuid)',
    'submit_note_version(uuid)',
    'submit_question_version(uuid)',
    'topic_prerequisite_chain(uuid)',
    'transfer_organisation_ownership(uuid,text)',
    'unpublish_note(uuid)',
    'unpublish_question(uuid)',
    'void_attempt(uuid,text)',
    'void_invoice(uuid,text)',
    'write_off_balance(uuid,bigint,text)'
  ]::text[];
$$ LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, public, pg_temp;

CREATE OR REPLACE FUNCTION public.security_verify()
RETURNS TABLE (check_name text, object_name text, detail text) AS $$
DECLARE
  v_expected text[] := public.security_expected_client_functions();
BEGIN
  -- 1. anon holds nothing on public objects
  RETURN QUERY
  SELECT 'anon_has_privilege', c.oid::regclass::text, c.relkind::text
  FROM pg_class c
  WHERE c.relnamespace IN ('public'::regnamespace, 'private'::regnamespace) AND c.relkind IN ('r','v','m','S','p')
    AND (has_table_privilege('anon', c.oid, 'SELECT') OR has_table_privilege('anon', c.oid, 'INSERT')
         OR has_table_privilege('anon', c.oid, 'UPDATE') OR has_table_privilege('anon', c.oid, 'DELETE')
         OR has_table_privilege('anon', c.oid, 'TRUNCATE'));
  RETURN QUERY
  SELECT 'anon_can_execute', p.oid::regprocedure::text, NULL::text
  FROM pg_proc p WHERE p.pronamespace IN ('public'::regnamespace, 'private'::regnamespace)
    AND has_function_privilege('anon', p.oid, 'EXECUTE');

  -- 2. No TRUNCATE / REFERENCES / TRIGGER for client roles or the backend; no TRUNCATE for service_role
  RETURN QUERY
  SELECT 'dangerous_table_privilege', c.oid::regclass::text, r.rolname || ':' || pr.priv
  FROM pg_class c
  CROSS JOIN (VALUES ('authenticated'), ('anon'), ('service_role')) r(rolname)
  CROSS JOIN (VALUES ('TRUNCATE'), ('REFERENCES'), ('TRIGGER')) pr(priv)
  WHERE c.relnamespace IN ('public'::regnamespace, 'private'::regnamespace) AND c.relkind IN ('r','p')
    AND has_table_privilege(r.rolname, c.oid, pr.priv);

  -- 3. authenticated EXECUTE set == reviewed allow-list (both directions)
  RETURN QUERY
  SELECT 'unexpected_client_function', p.oid::regprocedure::text, NULL::text
  FROM pg_proc p WHERE p.pronamespace IN ('public'::regnamespace, 'private'::regnamespace)
    AND has_function_privilege('authenticated', p.oid, 'EXECUTE')
    AND NOT (p.oid::regprocedure::text = ANY (v_expected));
  RETURN QUERY
  SELECT 'missing_client_function', e, NULL::text
  FROM unnest(v_expected) e
  WHERE NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace
                      AND p.oid::regprocedure::text = e AND has_function_privilege('authenticated', p.oid, 'EXECUTE'));

  -- 4. Every table in public has RLS enabled; private is unreachable by every API role
  RETURN QUERY
  SELECT 'rls_disabled', c.oid::regclass::text, NULL::text
  FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r','p') AND NOT c.relrowsecurity;
  RETURN QUERY
  SELECT 'private_schema_reachable', r.rolname, NULL::text
  FROM (VALUES ('anon'), ('authenticated'), ('service_role')) r(rolname)
  WHERE has_schema_privilege(r.rolname, 'private', 'USAGE');

  -- 5. Functions called by RLS policies are executable by authenticated
  RETURN QUERY
  WITH refs AS (
    SELECT DISTINCT p.polrelid::regclass::text AS tbl,
           (regexp_matches(COALESCE(pg_get_expr(p.polqual, p.polrelid), '') || ' ' ||
                           COALESCE(pg_get_expr(p.polwithcheck, p.polrelid), ''), '([a-z_][a-z0-9_]*)\(', 'g'))[1] AS fn
    FROM pg_policy p)
  SELECT DISTINCT 'policy_function_not_executable', r.fn, r.tbl
  FROM refs r
  WHERE EXISTS (SELECT 1 FROM pg_proc f WHERE f.proname = r.fn AND f.pronamespace = 'public'::regnamespace)
    AND NOT EXISTS (SELECT 1 FROM pg_proc f WHERE f.proname = r.fn AND f.pronamespace = 'public'::regnamespace
                      AND has_function_privilege('authenticated', f.oid, 'EXECUTE'));

  -- 6. SECURITY DEFINER functions pin a safe search_path (no "$user", no client-writable schema)
  RETURN QUERY
  SELECT 'secdef_search_path', p.oid::regprocedure::text, COALESCE(array_to_string(p.proconfig, ';'), 'none')
  FROM pg_proc p
  WHERE p.pronamespace IN ('public'::regnamespace, 'private'::regnamespace) AND p.prosecdef
    AND (p.proconfig IS NULL
         OR NOT EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%')
         OR EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%' AND c LIKE '%$user%'));
  RETURN QUERY
  SELECT 'schema_writable_by_client', n.nspname::text, r.rolname
  FROM pg_namespace n CROSS JOIN (VALUES ('anon'), ('authenticated'), ('service_role')) r(rolname)
  WHERE n.nspname IN ('public', 'extensions', 'private') AND has_schema_privilege(r.rolname, n.oid, 'CREATE');

  -- 7. Permission catalogue: every referenced code exists, and every catalogued code is used
  RETURN QUERY
  WITH src AS (
    SELECT p.prosrc AS txt FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace
             AND p.proname NOT IN ('security_verify', 'security_expected_client_functions')
    UNION ALL
    SELECT COALESCE(pg_get_expr(p.polqual, p.polrelid), '') || ' ' || COALESCE(pg_get_expr(p.polwithcheck, p.polrelid), '')
    FROM pg_policy p),
  refs AS (SELECT DISTINCT (regexp_matches(txt, 'has_permission\(\s*''([a-z_.]+)''', 'g'))[1] AS code FROM src)
  SELECT 'permission_missing', r.code, NULL::text FROM refs r
  WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.code = r.code)
  UNION ALL
  SELECT 'permission_unused', p.code, NULL::text FROM public.permissions p
  WHERE NOT EXISTS (SELECT 1 FROM refs r WHERE r.code = p.code);
  RETURN QUERY
  SELECT 'system_role_without_permissions', r.code, NULL::text
  FROM public.roles r
  WHERE r.organisation_id IS NULL AND r.code <> 'platform_admin'
    AND NOT EXISTS (SELECT 1 FROM public.role_permissions rp WHERE rp.role_id = r.id);

  -- 8. No executable legacy request-context architecture
  RETURN QUERY
  SELECT 'legacy_reference', p.oid::regprocedure::text, m[1]
  FROM pg_proc p, LATERAL regexp_matches(p.prosrc, '(app\.current_user|app\.current_org|app\.internal|set_request_context|app_user|payments_service|ai_worker)', 'g') m
  WHERE p.pronamespace IN ('public'::regnamespace, 'private'::regnamespace)
    AND p.proname NOT IN ('security_verify');
  RETURN QUERY
  SELECT 'legacy_reference', 'policy ' || p.polname, NULL::text FROM pg_policy p
  WHERE COALESCE(pg_get_expr(p.polqual, p.polrelid), '') || COALESCE(pg_get_expr(p.polwithcheck, p.polrelid), '')
        ~ '(app\.current|app\.internal|set_request_context)';
  RETURN QUERY
  SELECT 'legacy_role', r.rolname::text, NULL::text FROM pg_roles r
  WHERE r.rolname IN ('app_user', 'payments_service', 'ai_worker');
  RETURN QUERY
  SELECT 'legacy_column', (c.table_name || '.' || c.column_name)::text, NULL::text FROM information_schema.columns c
  WHERE c.table_schema = 'public' AND c.column_name = 'password_hash';
  RETURN QUERY
  SELECT 'legacy_table', c.relname::text, NULL::text FROM pg_class c
  WHERE c.relnamespace = 'public'::regnamespace AND c.relname = 'sessions';
END;
$$ LANGUAGE plpgsql STABLE SET search_path = pg_catalog, public, pg_temp;
REVOKE ALL ON FUNCTION public.security_verify(), public.security_expected_client_functions() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.security_verify(), public.security_expected_client_functions() TO service_role;

DO $$
DECLARE v text;
BEGIN
  SELECT string_agg(check_name || ' ' || object_name || COALESCE(' (' || detail || ')', ''), E'\n') INTO v
  FROM public.security_verify();
  IF v IS NOT NULL THEN
    RAISE EXCEPTION E'Security verification failed:\n%', v;
  END IF;
END $$;

INSERT INTO public.schema_migrations (version, description) VALUES ('010', 'foreign-key indexes and security verification (rev 6)');

COMMIT;
